import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:intl/intl.dart';\nimport '../models/subject.dart';\nimport '../models/homework.dart';\nimport '../providers/homework_providers.dart';\nimport 'package:cached_network_image/cached_network_image.dart';\n\nclass SubjectDetailsScreen extends ConsumerWidget {\n  final Subject subject;\n\n  const SubjectDetailsScreen({Key? key, required this.subject}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final currentHomeworkAsync = ref.watch(currentHomeworkProvider(subject.id));\n    final archiveHomeworkAsync = ref.watch(homeworkArchiveProvider(subject.id));\n\n    return Scaffold(\n      appBar: AppBar(\n        title: Text(subject.name),\n        centerTitle: true,\n      ),\n      body: RefreshIndicator(\n        onRefresh: () async {\n          // Re-fetch logic or just let stream handle it\n          ref.refresh(currentHomeworkProvider(subject.id));\n          ref.refresh(homeworkArchiveProvider(subject.id));\n        },\n        child: ListView(\n          padding: const EdgeInsets.all(16.0),\n          children: [\n            const Text(\n              'تحضير اليوم',\n              style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold, color: Colors.blue),\n            ),\n            const SizedBox(height: 10),\n            currentHomeworkAsync.when(\n              data: (homeworks) {\n                if (homeworks.isEmpty) {\n                  return const Card(\n                    child: Padding(\n                      padding: EdgeInsets.all(16.0),\n                      child: Text('لا يوجد تحضير لليوم'),\n                    ),\n                  );\n                }\n                return _buildHomeworkCard(context, homeworks.first, isCurrent: true);\n              },\n              loading: () => const Center(child: CircularProgressIndicator()),\n              error: (err, stack) => Text('خطأ: $err'),\n            ),\n            \n            const SizedBox(height: 32),\n            const Text(\n              'أرشيف التحاضير السابقة',\n              style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: Colors.grey),\n            ),\n            const SizedBox(height: 10),\n            archiveHomeworkAsync.when(\n              data: (homeworks) {\n                if (homeworks.isEmpty) {\n                  return const Text('لا توجد تحاضير سابقة');\n                }\n                return ListView.builder(\n                  shrinkWrap: true,\n                  physics: const NeverScrollableScrollPhysics(),\n                  itemCount: homeworks.length,\n                  itemBuilder: (context, index) {\n                    return _buildHomeworkCard(context, homeworks[index], isCurrent: false);\n                  },\n                );\n              },\n              loading: () => const Center(child: CircularProgressIndicator()),\n              error: (err, stack) => Text('خطأ: $err'),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildHomeworkCard(BuildContext context, Homework hw, {required bool isCurrent}) {\n    final DateFormat formatter = DateFormat('yyyy-MM-dd HH:mm');\n    final dateString = formatter.format(hw.createdAt);\n\n    return Card(\n      elevation: isCurrent ? 4 : 1,\n      color: isCurrent ? Colors.blue.shade50 : Colors.white,\n      margin: const EdgeInsets.only(bottom: 16),\n      shape: RoundedRectangleBorder(\n        borderRadius: BorderRadius.circular(12),\n        side: isCurrent ? BorderSide(color: Colors.blue.shade300, width: 2) : BorderSide.none,\n      ),\n      child: Padding(\n        padding: const EdgeInsets.all(16.0),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                Expanded(\n                  child: Text(\n                    hw.title,\n                    style: TextStyle(\n                      fontSize: 18, \n                      fontWeight: FontWeight.bold, \n                      color: isCurrent ? Colors.black87 : Colors.black54\n                    ),\n                  ),\n                ),\n                Text(\n                  dateString,\n                  style: const TextStyle(fontSize: 12, color: Colors.grey),\n                ),\n              ],\n            ),\n            const Divider(),\n            Text(\n              hw.description,\n              style: const TextStyle(fontSize: 16, height: 1.5),\n            ),\n            if (hw.imageUrl != null && hw.imageUrl!.isNotEmpty) ...[\n              const SizedBox(height: 16),\n              ClipRRect(\n                borderRadius: BorderRadius.circular(8),\n                child: CachedNetworkImage(\n                  imageUrl: hw.imageUrl!,\n                  placeholder: (context, url) => const Center(child: CircularProgressIndicator()),\n                  errorWidget: (context, url, error) => const Icon(Icons.error),\n                  fit: BoxFit.cover,\n                  width: double.infinity,\n                ),\n              )\n            ]\n          ],\n        ),\n      ),\n    );\n  }\n}\n